import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const g=JSON.parse('{"title":"SSE, Bounded Polling and gRPC: Choosing a Transport — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/realtime-transports.md","filePath":"practice/node-js/realtime-transports.md"}'),o={name:"practice/node-js/realtime-transports.md"};function s(i,e,c,d,p,l){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="sse-bounded-polling-and-grpc-choosing-a-transport-—-practice" tabindex="-1">SSE, Bounded Polling and gRPC: Choosing a Transport — practice <a class="header-anchor" href="#sse-bounded-polling-and-grpc-choosing-a-transport-—-practice" aria-label="Permalink to “SSE, Bounded Polling and gRPC: Choosing a Transport — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/realtime-transports.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="practice-and-acceptance-evidence" tabindex="-1">Practice and acceptance evidence <a class="header-anchor" href="#practice-and-acceptance-evidence" aria-label="Permalink to “Practice and acceptance evidence”">​</a></h2><p><strong>SSE:</strong> use an authorized scratch feed, take a snapshot and stream later IDs; reconnect with Last-Event-ID and require no missing retained events. Expire replay history and verify reset/resnapshot; test malformed/future cursors before headers, duplicate delivery, slow response pressure, disconnect and shutdown cleanup. Observe heartbeat bytes through the actual proxy and native EventSource reconnection. Require listener/timer/subscriber counts return to baseline. Explain in-memory restart/durability and side-effect idempotency limitations. A callback fixture cannot establish browser/proxy behavior.</p><p><strong>Polling:</strong> control the clock and request adapter. Require one active attempt maximum, next schedule only after completion, bounded delay/jitter, selected transient retry, terminal failure stop, disposal during in-flight work and no consume after stop. Test invalid schema,304, timeout and cancellation using the real fetch adapter in the practice app. State whether the owner is a bounded job or a long-lived view and enforce its retry budget accordingly.</p><p><strong>gRPC introductory exercise:</strong> explain both proto methods and four RPC forms; map a not-found/auth/deadline failure to the right gRPC status and external HTTP response; propose a compatible schema addition and unsafe field-number reuse. Acceptance: describe channel/auth/deadline/stream cleanup and browser gateway trade-offs correctly. Running the official Node quickstart and a streaming/load/deployment experiment is optional advanced practice, explicitly not completed here.</p><p>References checked2026-10-21: <a href="https://html.spec.whatwg.org/multipage/server-sent-events.html" target="_blank" rel="noreferrer">HTML SSE/EventSource</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/http.html" target="_blank" rel="noreferrer">Node24 HTTP</a>, <a href="https://grpc.io/docs/languages/node/basics/" target="_blank" rel="noreferrer">gRPC Node basics</a>, <a href="https://grpc.io/docs/what-is-grpc/core-concepts/" target="_blank" rel="noreferrer">gRPC concepts/status</a>, <a href="https://grpc.io/docs/guides/deadlines/" target="_blank" rel="noreferrer">deadlines</a>, <a href="https://grpc.io/docs/what-is-grpc/faq/" target="_blank" rel="noreferrer">gRPC browser FAQ</a>, <a href="https://protobuf.dev/programming-guides/proto3/#updating" target="_blank" rel="noreferrer">protobuf schema evolution</a>.</p>',8)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
